sp_widget.client_script:
api.controller = function () {
    /* widget controller */
    var c = this;
};

sp_widget.css:
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
  flex-shrink: 0;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon {
  margin-right: 8px;
  color: $brand-primary;
  font-size: 16px;
}
.sp-card-body {
  padding: 24px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}
.sp-link-item {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border: none;
  border-bottom: 1px solid $border-tertiary;
  cursor: pointer;
  transition: background 0.15s;
  &:last-child {
    border-bottom: none;
  }
  &:hover {
    background: $background-secondary;
  }
}
.sp-link-icon {
  font-size: 20px;
  color: $brand-primary;
  margin-right: 12px;
  flex-shrink: 0;
}
.sp-link-text {
  flex: 1;
  p {
    margin: 2px 0 0;
    font-size: $font-size-small;
  }
}
.sp-link-chevron {
  color: $text-muted;
  font-size: 12px;
}

sp_widget.script:
(function() {
  data.links = [];

  data.links.push({
    title: 'Flash Dashboard',
    icon: 'glyphicon-dashboard',
    description: 'View flash notification metrics'
  });
  data.links.push({
    title: 'User Guide',
    icon: 'glyphicon-book',
    description: 'Learn how to use Flash'
  });
  data.links.push({
    title: 'Contact Support',
    icon: 'glyphicon-envelope',
    description: 'Get help from the Flash team'
  });
  data.links.push({
    title: 'FAQs',
    icon: 'glyphicon-question-sign',
    description: 'Frequently asked questions'
  });
})();
